      var ex = 0, ey = inside ? -Ev : 0, bz = inside ? -Bt : 0, k = q * dt / (2 * m);
      var ux = vx + k * ex, uy = vy + k * ey, tz = k * bz, sz = 2 * tz / (1 + tz * tz);
      var px = ux + uy * tz, py = uy - ux * tz;
      ux = ux + py * sz; uy = uy - px * sz;
      vx = ux + k * ex; vy = uy + k * ey;
      x += vx * dt; y += vy * dt; t += dt;
      if (inside) { tin += dt; entered = true; } else if (entered && !left) left = true;
      pts.push([x * 100, y * 100, t]);
