    ctx.save(); ctx.fillStyle = t.violet; ctx.globalAlpha = 0.08; ctx.fillRect(a[0], 0, b2[0] - a[0], s.h); ctx.restore();
    ctx.save(); ctx.strokeStyle = t.violet; ctx.globalAlpha = 0.6; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.moveTo(a[0], 0); ctx.lineTo(a[0], s.h); ctx.moveTo(b2[0], 0); ctx.lineTo(b2[0], s.h); ctx.stroke(); ctx.restore();
    var stepPx = Math.max(26, 6 * s.scale);
