        var ccx = ent[0] - Math.sin(ang) * r * sg, ccy = ent[1] + Math.cos(ang) * r * sg, c = s.toScreen(ccx, ccy);
        ctx.save(); ctx.strokeStyle = t.ink3; ctx.globalAlpha = 0.5; ctx.setLineDash([4, 6]); ctx.lineWidth = 1.2; ctx.beginPath(); ctx.arc(c[0], c[1], r * s.scale, 0, 7); ctx.stroke(); ctx.restore();
