    if (t0 === null && s.animating()) t0 = performance.now();
    var tNow = s.animating() ? ((performance.now() - t0) / 1000) * speedUp / scale : tEnd;
    if (tNow >= tEnd) { tNow = tEnd; stage.setAnimating(false); }
    ctx.save(); ctx.strokeStyle = t.accent; ctx.lineWidth = 2.6; ctx.lineJoin = 'round'; ctx.beginPath();
    var head = path[0];
    for (i = 0; i < path.length && path[i][2] <= tNow; i++) { var q = s.toScreen(path[i][0], path[i][1]); i ? ctx.lineTo(q[0], q[1]) : ctx.moveTo(q[0], q[1]); head = path[i]; }
    ctx.stroke(); ctx.restore();
    var hp = s.toScreen(head[0], head[1]);
    ctx.save(); ctx.fillStyle = P.q > 0 ? t.pos : t.neg; ctx.beginPath(); ctx.arc(hp[0], hp[1], 7, 0, 7); ctx.fill(); ctx.restore();
    Sim.label(ctx, P.q > 0 ? '+' : '−', hp[0], hp[1], { size: 11, weight: 800, color: '#fff' });
    if (speedUp > 1.05 && tNow < tEnd) Sim.label(ctx, '×' + speedUp.toFixed(1) + ' playback', s.w - 12, 14, { size: 11, weight: 650, color: t.ink3, align: 'right' });

    // launch arrow + handle
