    Sim.arrow(ctx, L0[0], L0[1], L1[0], L1[1], { color: t.warn, width: 2.6, head: 10 });
    ctx.save(); ctx.fillStyle = t.warn; ctx.globalAlpha = H.active || s.focused(H) ? 0.4 : 0.18; ctx.beginPath(); ctx.arc(L1[0], L1[1], 13, 0, 7); ctx.fill(); ctx.restore();
    Sim.label(ctx, 'v', L1[0] + 10, L1[1] - 12, { size: 13, weight: 800, color: t.warn });

